const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const to = [], cap = [], cost = [], adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < m; i++) {
  const u = tok[2 + 4 * i], v = tok[3 + 4 * i], c = tok[4 + 4 * i], w = tok[5 + 4 * i];
  adj[u].push(to.length); to.push(v); cap.push(c); cost.push(w);
  adj[v].push(to.length); to.push(u); cap.push(0); cost.push(-w);
}
const INF = 1e18;
let flow = 0, total = 0;
for (;;) {
  const dist = new Array(n + 1).fill(INF), inq = new Array(n + 1).fill(false), pe = new Array(n + 1).fill(-1);
  dist[1] = 0;
  const q = [1];
  for (let h = 0; h < q.length; h++) {
    const v = q[h];
    inq[v] = false;
    for (const e of adj[v]) {
      if (cap[e] > 0 && dist[v] + cost[e] < dist[to[e]]) {
        dist[to[e]] = dist[v] + cost[e];
        pe[to[e]] = e;
        if (!inq[to[e]]) { inq[to[e]] = true; q.push(to[e]); }
      }
    }
  }
  if (dist[n] === INF) break;
  let f = INF;
  for (let v = n; v !== 1; v = to[pe[v] ^ 1]) f = Math.min(f, cap[pe[v]]);
  for (let v = n; v !== 1; v = to[pe[v] ^ 1]) { cap[pe[v]] -= f; cap[pe[v] ^ 1] += f; }
  flow += f;
  total += f * dist[n];
}
console.log(flow + " " + total);

