import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[] to = new int[2 * m];
        long[] cap = new long[2 * m], cost = new long[2 * m];
        List<Integer>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            in.nextToken(); int u = (int) in.nval;
            in.nextToken(); int v = (int) in.nval;
            in.nextToken(); long c = (long) in.nval;
            in.nextToken(); long w = (long) in.nval;
            adj[u].add(2 * i); to[2 * i] = v; cap[2 * i] = c; cost[2 * i] = w;
            adj[v].add(2 * i + 1); to[2 * i + 1] = u; cost[2 * i + 1] = -w;
        }
        final long INF = Long.MAX_VALUE / 4;
        long flow = 0, total = 0;
        while (true) {
            long[] dist = new long[n + 1];
            Arrays.fill(dist, INF);
            dist[1] = 0;
            boolean[] inq = new boolean[n + 1];
            int[] pe = new int[n + 1];
            Arrays.fill(pe, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.add(1);
            while (!q.isEmpty()) {
                int v = q.poll();
                inq[v] = false;
                for (int e : adj[v]) {
                    if (cap[e] > 0 && dist[v] + cost[e] < dist[to[e]]) {
                        dist[to[e]] = dist[v] + cost[e];
                        pe[to[e]] = e;
                        if (!inq[to[e]]) { inq[to[e]] = true; q.add(to[e]); }
                    }
                }
            }
            if (dist[n] == INF) break;
            long f = INF;
            for (int v = n; v != 1; v = to[pe[v] ^ 1]) f = Math.min(f, cap[pe[v]]);
            for (int v = n; v != 1; v = to[pe[v] ^ 1]) { cap[pe[v]] -= f; cap[pe[v] ^ 1] += f; }
            flow += f;
            total += f * dist[n];
        }
        System.out.println(flow + " " + total);
    }
}

