#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    vector<int> to;
    vector<ll> cap, cost;
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        ll c, w;
        scanf("%d %d %lld %lld", &u, &v, &c, &w);
        adj[u].push_back(to.size()); to.push_back(v); cap.push_back(c); cost.push_back(w);
        adj[v].push_back(to.size()); to.push_back(u); cap.push_back(0); cost.push_back(-w);
    }
    const ll INF = LLONG_MAX / 4;
    ll flow = 0, total = 0;
    while (true) {
        vector<ll> dist(n + 1, INF);
        vector<bool> inq(n + 1, false);
        vector<int> pe(n + 1, -1);
        dist[1] = 0;
        queue<int> q;
        q.push(1);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            inq[v] = false;
            for (int e : adj[v]) {
                if (cap[e] > 0 && dist[v] + cost[e] < dist[to[e]]) {
                    dist[to[e]] = dist[v] + cost[e];
                    pe[to[e]] = e;
                    if (!inq[to[e]]) { inq[to[e]] = true; q.push(to[e]); }
                }
            }
        }
        if (dist[n] == INF) break;
        ll f = INF;
        for (int v = n; v != 1; v = to[pe[v] ^ 1]) f = min(f, cap[pe[v]]);
        for (int v = n; v != 1; v = to[pe[v] ^ 1]) { cap[pe[v]] -= f; cap[pe[v] ^ 1] += f; }
        flow += f;
        total += f * dist[n];
    }
    printf("%lld %lld\n", flow, total);
    return 0;
}
